// Scalar, paraxial Fourier optics. All pupil-plane lengths are SI metres.
export const N=1024, PUPIL_PIXELS=512, LAMBDA=550e-9;
export function residualCylinder(s){return s.glasses?0:s.astig*(s.toric?2*Math.abs(Math.sin(s.rotation*Math.PI/180)):1);}
export function fft1(re,im,inverse=false){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]];}}for(let len=2;len<=n;len<<=1){const a=(inverse?2:-2)*Math.PI/len,wr0=Math.cos(a),wi0=Math.sin(a);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){const k=i+j,l=k+len/2,tr=re[l]*wr-im[l]*wi,ti=re[l]*wi+im[l]*wr;re[l]=re[k]-tr;im[l]=im[k]-ti;re[k]+=tr;im[k]+=ti;const temp=wr*wr0-wi*wi0;wi=wr*wi0+wi*wr0;wr=temp;}}}if(inverse)for(let i=0;i<n;i++){re[i]/=n;im[i]/=n;}}
export function fft2(re,im,w,h,inverse=false){for(let y=0;y<h;y++)fft1(re.subarray(y*w,(y+1)*w),im.subarray(y*w,(y+1)*w),inverse);const a=new Float64Array(h),b=new Float64Array(h);for(let x=0;x<w;x++){for(let y=0;y<h;y++){a[y]=re[y*w+x];b[y]=im[y*w+x];}fft1(a,b,inverse);for(let y=0;y<h;y++){re[y*w+x]=a[y];im[y*w+x]=b[y];}}}
function z40(x,y){const r2=x*x+y*y;return Math.sqrt(5)*(6*r2*r2-6*r2+1);}
export function opticalPSF(s){const re=new Float64Array(N*N),im=new Float64Array(N*N),D=s.pupil/1000,R=D/2,rp=PUPIL_PIXELS/2,rot=s.rotation*Math.PI/180,c2=Math.cos(2*rot),s2=Math.sin(2*rot),C=s.glasses?0:s.astig,sa=.20e-6*(s.pupil/6)**4,dx=s.decenter/1000/R,defocus=s.scene==='reading'?-s.distance:0;let count=0;
for(let y=0;y<N;y++)for(let x=0;x<N;x++){const u=(x-N/2)/rp,v=(y-N/2)/rp,r2=u*u+v*v;if(r2>1)continue;let W=defocus*R*R*r2/2+C*R*R*(u*u-v*v)/4;if(s.toric)W-=C*R*R*((u*u-v*v)*c2+2*u*v*s2)/4;W+=sa*z40(u,v);if(s.aspheric){ // Recenter the PSF: remove the induced piston and pupil-average wavefront tilt.
const shifted=z40(u-dx,v);const tilt=-Math.sqrt(5)*(12*dx+24*dx**3)*u;
W-=sa*(shifted-tilt);
}const phase=2*Math.PI*W/LAMBDA,i=y*N+x;re[i]=Math.cos(phase);im[i]=Math.sin(phase);count++;}
fft2(re,im,N,N);const psf=new Float64Array(N*N);let sum=0;for(let y=0;y<N;y++)for(let x=0;x<N;x++){const i=((y+N/2)%N)*N+(x+N/2)%N;const v=re[i]*re[i]+im[i]*im[i];psf[y*N+x]=v;sum+=v;}for(let i=0;i<psf.length;i++)psf[i]/=sum;
return {psf,angle:LAMBDA*PUPIL_PIXELS/(D*N),pupilSamples:count};}
export function mtfCurves(psf,angle,pupil){const re=new Float64Array(psf),im=new Float64Array(psf.length);fft2(re,im,N,N);const horizontal=[],vertical=[],ideal=[],fieldDeg=N*angle*180/Math.PI,cutoff=(pupil/1000)/LAMBDA*Math.PI/180;const sample=(arr,k,axis)=>{const j=Math.floor(k),t=k-j;const i1=axis==='x'?j:j*N,i2=axis==='x'?j+1:(j+1)*N;return arr[i1]*(1-t)+arr[i2]*t;}; // Magnitudes remove fftshift's alternating phase before interpolation.
const mag=new Float64Array(re.length);for(let i=0;i<mag.length;i++)mag[i]=Math.hypot(re[i],im[i]);for(let f=0;f<=40;f++){horizontal.push(Math.max(0,Math.min(1,sample(mag,f*fieldDeg,'x'))));vertical.push(Math.max(0,Math.min(1,sample(mag,f*fieldDeg,'y'))));const nu=Math.min(1,f/cutoff);ideal.push(2/Math.PI*(Math.acos(nu)-nu*Math.sqrt(1-nu*nu)));}return{horizontal,vertical,ideal};}
export function sceneKernel(psf,angle,pixelAngle){const size=129,mid=64,k=new Float64Array(size*size);let retained=0;for(let y=0;y<N;y++)for(let x=0;x<N;x++){const u=(x-N/2)*angle/pixelAngle+mid,v=(y-N/2)*angle/pixelAngle+mid,ix=Math.floor(u),iy=Math.floor(v),tx=u-ix,ty=v-iy,p=psf[y*N+x];for(let dy=0;dy<=1;dy++)for(let dx=0;dx<=1;dx++){const xx=ix+dx,yy=iy+dy;if(xx>=0&&xx<size&&yy>=0&&yy<size){const a=p*(dx?tx:1-tx)*(dy?ty:1-ty);k[yy*size+xx]+=a;retained+=a;}}}for(let i=0;i<k.length;i++)k[i]/=retained;return{kernel:k,size,retained};}
export function linear(v){v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}
export function srgb(v){v=Math.max(0,Math.min(1,v));return Math.round(255*(v<=.0031308?12.92*v:1.055*v**(1/2.4)-.055));}
